def solve():
    n = 6
    triangles = list(itertools.combinations(range(n), 3))
    # We want to pick 10 triangles out of 20 such that each edge is used exactly 2 times.
    # Total edges = 15. Each triangle uses 3 edges. 10*3 = 30. 30/15 = 2.

    edges = list(itertools.combinations(range(n), 2))
    edge_to_idx = {edge: i for i, edge in enumerate(edges)}

    # Represent each triangle as a set of edge indices
    triangle_edges = []
    for tri in triangles:
        tri_edges = []
        for i in range(3):
            for j in range(i + 1, 3):
                tri_edges.append(edge_to_idx[tuple(sorted((tri[i], tri[j])))])
        triangle_edges.append(tri_edges)

    # Use backtracking to find a set of 10 triangles
    def backtrack(start_idx, current_triangles, current_edge_counts):
        if len(current_triangles) == 10:
            if all(count == 2 for count in current_edge_counts):
                return True
            return False

        for i in range(start_idx, len(triangle_edges)):
            tri = triangle_edges[i]
            # Check if we can add this triangle
            possible = True
            for edge_idx in tri:
                if current_edge_counts[edge_idx] >= 2:
                    possible = False
                    break

            if possible:
                for edge_idx in tri:
                    current_edge_counts[edge_idx] += 1
                current_triangles.append(i)
                if backtrack(i + 1, current_triangles, current_edge_counts):
                    return True
                current_triangles.pop()
                for edge_idx in tri:
                    current_edge_counts[edge_idx] -= 1
        return False

